({ datos, tema, UI, MEITI }) => {
  const eco = MEITI.obtenerEcosistemaActual();
  const miId = MEITI.obtenerUsuarioActual();
  const base = '/api/boveda/' + MEITI.obtenerTabla('roles_usuarios_app');

  const [filas, setFilas] = React.useState([]);
  const [cargando, setCargando] = React.useState(true);
  const [nuevoId, setNuevoId] = React.useState('');
  const [nuevoRol, setNuevoRol] = React.useState('lector');
  const [aviso, setAviso] = React.useState(null);

  const cargar = async () => {
    setCargando(true);
    const resultado = await MEITI.fetchDatos(base + '?ecosistema=' + eco);
    if (resultado.ok) setFilas(resultado.registros);
    setCargando(false);
  };

  React.useEffect(() => { cargar(); }, []);

  const miFila = filas.find(f => f.usuario_id === miId);
  const soyDueno = MEITI.soyDuenoDeLaApp ? MEITI.soyDuenoDeLaApp() : false;
  const soyAdmin = soyDueno || (miFila ? miFila.rol === 'admin' : filas.length === 0);
  const cuantosAdmins = filas.filter(f => f.rol === 'admin').length;

  const volverseAdmin = async () => {
    const r = await MEITI.fetchMutante(base + '?ecosistema=' + eco, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ id: 'rol_' + Date.now(), usuario_id: miId, email_visible: miId.startsWith('email_') ? miId.replace('email_', '') : miId, rol: 'admin' })
    });
    if (r && r.ok === false) { setAviso('No se pudo completar la acción. Vuelve a intentarlo.'); return; }
    cargar();
  };

  const agregarUsuario = async (e) => {
    e.preventDefault();
    if (!nuevoId.trim()) { setAviso('Falta el email del usuario.'); return; }
    const r = await MEITI.fetchMutante(base + '?ecosistema=' + eco, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ id: 'rol_' + Date.now(), usuario_id: 'email_' + nuevoId.trim().toLowerCase(), email_visible: nuevoId.trim(), rol: nuevoRol })
    });
    if (r && r.ok === false) { setAviso('No se pudo agregar el usuario. Vuelve a intentarlo.'); return; }
    setNuevoId('');
    setNuevoRol('lector');
    cargar();
  };

  const cambiarRol = async (fila, rolNuevo) => {
    if (fila.rol === 'admin' && rolNuevo !== 'admin' && cuantosAdmins <= 1) {
      setAviso('No puedes quitarle el rol de administrador al último que queda. Nombra antes a otro.');
      return;
    }
    const r = await MEITI.fetchMutante(base + '?ecosistema=' + eco, {
      method: 'PUT',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ id: fila.id, usuario_id: fila.usuario_id, email_visible: fila.email_visible, rol: rolNuevo })
    });
    if (r && r.ok === false) { setAviso('No se pudo cambiar el rol. Vuelve a intentarlo.'); return; }
    cargar();
  };

  const quitarUsuario = async (fila) => {
    if (fila.usuario_id === miId) { setAviso('No puedes quitarte a ti mismo.'); return; }
    if (fila.rol === 'admin' && cuantosAdmins <= 1) {
      setAviso('No puedes quitar al último administrador: la app quedaría sin nadie que pueda administrarla. Nombra antes a otro.');
      return;
    }
    if (!await MEITI.confirmar('¿Quitar a ' + (fila.email_visible || fila.usuario_id) + '?')) return;
    const r = await MEITI.fetchMutante(base + '?ecosistema=' + eco + '&id=' + fila.id, { method: 'DELETE' });
    if (r && r.ok === false) { setAviso('No se pudo quitar al usuario. Vuelve a intentarlo.'); return; }
    cargar();
  };

  const columnas = [
    {
      clave: 'usuario',
      etiqueta: MEITI.t('user_column', null, "Usuario"),
      render: (f) => (
        <span>{f.email_visible || f.usuario_id}{f.usuario_id === miId ? ' (tú)' : ''}</span>
      )
    },
    {
      clave: 'rol',
      etiqueta: MEITI.t('role_column', null, "Rol"),
      render: (f) => (
        soyAdmin && f.usuario_id !== miId ? (
          <UI.Desplegable
            tamano="compacto"
            valor={f.rol}
            onCambio={(e) => cambiarRol(f, e.target.value)}
            opciones={[{ value: 'admin', label: MEITI.t('admin_role_option', null, 'admin') }, { value: 'editor', label: MEITI.t('editor_role_option', null, 'editor') }, { value: 'lector', label: MEITI.t('reader_role_option', null, 'lector') }]}
          />
        ) : (
          <UI.Chip tono={f.rol === 'admin' ? 'exito' : f.rol === 'editor' ? 'alerta' : 'neutro'}>{f.rol}</UI.Chip>
        )
      )
    }
  ];

  const accionesExtra = soyAdmin ? [
    {
      etiqueta: MEITI.t('remove_button', null, "Quitar"),
      icono: 'fa-user-slash',
      tono: 'peligro',
      onClick: (f) => quitarUsuario(f),
      condicion: (f) => f.usuario_id !== miId
    }
  ] : [];

  return (
    <UI.Tarjeta>
      <h3 style={{color: tema.texto, marginBottom: '0.5rem', fontSize: '1.2rem', fontWeight: 'bold'}}>{MEITI.t('panel_title', null, "Roles y permisos")}</h3>
      <p style={{color: tema.texto, opacity: 0.6, fontSize: '0.75rem', marginBottom: '1rem'}}>{MEITI.t('panel_subtitle', null, "Molde base del sistema — control de acceso de esta app.")}</p>

      {aviso && <UI.Aviso mensaje={aviso} tono="alerta" onCerrar={() => setAviso(null)} />}

      {cargando ? (
        <p style={{color: tema.texto}}>{MEITI.t('loading_state', null, "Cargando...")}</p>
      ) : filas.length === 0 ? (
        <div>
          <UI.EstadoVacio icono="fa-user-shield" mensaje={MEITI.t('empty_admins_message', null, "Todavía no hay administradores en esta app.")} />
          <UI.Boton onClick={volverseAdmin}>{MEITI.t('self_promote_button', null, "Volverme administrador")}</UI.Boton>
        </div>
      ) : (
        <UI.TablaDatos
          columnas={columnas}
          datos={filas}
          claveId="id"
          accionesExtra={accionesExtra}
          advertirAccionIncompleta={false}
        />
      )}

      {soyAdmin && filas.length > 0 && (
        <form onSubmit={agregarUsuario} style={{marginTop: '1.5rem', display: 'flex', gap: '0.75rem', alignItems: 'flex-end', flexWrap: 'wrap'}}>
          <div style={{flex: 1, minWidth: '180px'}}>
            <UI.Campo etiqueta={MEITI.t('add_user_label', null, "Agregar usuario (email)")} valor={nuevoId} onChange={(e) => setNuevoId(e.target.value)} placeholder={MEITI.t('email_placeholder', null, "persona@email.com")} />
          </div>
          <div style={{minWidth: '140px'}}>
            <UI.Campo etiqueta={MEITI.t('role_column', null, "Rol")} tipo="select" valor={nuevoRol} onChange={(e) => setNuevoRol(e.target.value)} opciones={[{value:'admin', label:MEITI.t('admin_role_option', null, 'admin')}, {value:'editor', label:MEITI.t('editor_role_option', null, 'editor')}, {value:'lector', label:MEITI.t('reader_role_option', null, 'lector')}]} />
          </div>
          <UI.Boton tipo="submit">{MEITI.t('add_button', null, "Agregar")}</UI.Boton>
        </form>
      )}
    </UI.Tarjeta>
  );
}

({ datos, tema, UI, MEITI }) => {
  const eco = MEITI.obtenerEcosistemaActual();
  const miId = MEITI.obtenerUsuarioActual();
  const [perfil, setPerfil] = useState(null);
  const [cargando, setCargando] = useState(true);

  useEffect(() => {
    const cargar = async () => {
      setCargando(true);
      const res = await MEITI.fetchDatosPropios(`/api/boveda/${MEITI.obtenerTabla('ll_perfiles')}?ecosistema=${eco}`);
      if (res.ok && res.registros.length > 0) {
        setPerfil(res.registros[0]);
      } else {
        const nuevoPerfil = { id: 'perf_' + miId, usuario_id: miId, estudiante_id: miId, nombre: 'Estudiante', puntos: 0, racha: 0 };
        await MEITI.mutar(`/api/boveda/${MEITI.obtenerTabla('ll_perfiles')}?ecosistema=${eco}`, { method: 'POST', headers: {'Content-Type':'application/json'}, body: JSON.stringify(nuevoPerfil) }, { alLograr: () => setPerfil(nuevoPerfil) });
      }
      setCargando(false);
    };
    cargar();
  }, []);

  if (cargando) return <div className="p-8 text-center"><Iconos.LoaderCircle className="animate-spin mx-auto" size={32} color={tema.colorPrimario} /></div>;

  return (
    <div className="flex flex-col gap-6 pb-28">
      <div className="flex items-center justify-between px-2">
        <h1 className="text-2xl font-black" style={{ color: tema.texto }}>{MEITI.t('ll_home_title', null, 'Tu Progreso')}</h1>
        <div className="w-10 h-10 rounded-full bg-black/10 flex items-center justify-center">
          <Iconos.User size={20} color={tema.texto} />
        </div>
      </div>

      <div className="grid grid-cols-2 gap-4">
        <Animacion.motion.div initial={{ opacity: 0, y: 10 }} animate={{ opacity: 1, y: 0 }} transition={{ duration: 0.3 }}>
          <UI.Tarjeta className="flex flex-col items-center justify-center p-6 text-center gap-2">
            <Iconos.Flame size={40} color={tema.colorSecundario} />
            <span className="text-3xl font-black" style={{ color: tema.texto }}>{perfil?.racha || 0}</span>
            <span className="text-sm font-bold opacity-70 uppercase tracking-wider" style={{ color: tema.texto }}>{MEITI.t('ll_streak_days', null, 'Días de racha')}</span>
          </UI.Tarjeta>
        </Animacion.motion.div>

        <Animacion.motion.div initial={{ opacity: 0, y: 10 }} animate={{ opacity: 1, y: 0 }} transition={{ duration: 0.3, delay: 0.1 }}>
          <UI.Tarjeta className="flex flex-col items-center justify-center p-6 text-center gap-2">
            <Iconos.Star size={40} color={tema.colorPrimario} />
            <span className="text-3xl font-black" style={{ color: tema.texto }}>{perfil?.puntos || 0}</span>
            <span className="text-sm font-bold opacity-70 uppercase tracking-wider" style={{ color: tema.texto }}>{MEITI.t('ll_total_points', null, 'Puntos EXP')}</span>
          </UI.Tarjeta>
        </Animacion.motion.div>
      </div>

      <UI.Tarjeta className="p-6 flex flex-col gap-4 mt-4">
        <div className="flex items-center gap-3">
          <Iconos.Target size={24} color={tema.colorPrimario} />
          <h2 className="text-xl font-bold" style={{ color: tema.texto }}>{MEITI.t('ll_ready_to_learn', null, '¿Listo para aprender?')}</h2>
        </div>
        <p className="opacity-80 text-sm" style={{ color: tema.texto }}>{MEITI.t('ll_home_desc', null, 'Continúa tu camino de aprendizaje y mantén tu racha activa.')}</p>
        <button 
          onClick={() => MEITI.irAPagina('camino')}
          className="w-full py-4 rounded-2xl font-black text-lg shadow-lg transition-transform active:scale-95 flex items-center justify-center gap-2 mt-2"
          style={{ background: tema.colorPrimario, color: '#fff' }}
        >
          {MEITI.t('ll_btn_continue', null, 'Continuar Ruta')}
          <Iconos.ArrowRight size={20} />
        </button>
      </UI.Tarjeta>
    </div>
  );
}

({ datos, tema, UI, MEITI }) => {
  const eco = MEITI.obtenerEcosistemaActual();
  const miId = MEITI.obtenerUsuarioActual();
  const [unidades, setUnidades] = useState([]);
  const [lecciones, setLecciones] = useState([]);
  const [progreso, setProgreso] = useState([]);
  const [cargando, setCargando] = useState(true);
  const [error, setError] = useState(null);

  useEffect(() => {
    const cargar = async () => {
      setCargando(true);
      const [resUni, resLec, resProg] = await Promise.all([
        MEITI.fetchDatos(`/api/boveda/${MEITI.obtenerTabla('ll_unidades')}?ecosistema=${eco}`),
        MEITI.fetchDatos(`/api/boveda/${MEITI.obtenerTabla('ll_lecciones')}?ecosistema=${eco}`),
        MEITI.fetchDatosPropios(`/api/boveda/${MEITI.obtenerTabla('ll_progreso')}?ecosistema=${eco}`)
      ]);
      if (resUni.ok) setUnidades(resUni.registros.sort((a, b) => a.orden - b.orden));
      if (resLec.ok) setLecciones(resLec.registros.sort((a, b) => a.orden - b.orden));
      if (resProg.ok) setProgreso(resProg.registros);
      setCargando(false);
    };
    cargar();
  }, []);

  const iniciarLeccion = async (leccion) => {
    const payload = { id: 'sesion_' + miId, usuario_id: miId, leccion_id: leccion.id };
    await MEITI.mutar(`/api/boveda/${MEITI.obtenerTabla('ll_sesion_activa')}?ecosistema=${eco}`, {
      method: 'PUT',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify(payload)
    }, {
      alLograr: () => MEITI.irAPagina('leccion'),
      alFallar: setError
    });
  };

  const esCompletada = (id) => progreso.some(p => p.leccion_id === id && p.completada === 1);

  if (cargando) return <div className="p-8 text-center"><Iconos.LoaderCircle className="animate-spin mx-auto" size={32} color={tema.colorPrimario} /></div>;

  return (
    <div className="flex flex-col gap-8 pb-32 px-2">
      <UI.Aviso mensaje={error} tono="peligro" onCerrar={() => setError(null)} />

      {unidades.length === 0 ? (
        <UI.EstadoVacio icono="fa-map" mensaje={MEITI.t('ll_no_units', null, 'Aún no hay unidades disponibles.')} />
      ) : (
        unidades.map((u, i) => {
          const lecs = lecciones.filter(l => l.unidad_id === u.id);
          return (
            <div key={u.id} className="flex flex-col gap-6">
              <div className="p-6 rounded-3xl shadow-sm" style={{ background: tema.colorPrimario, color: '#fff' }}>
                <h2 className="text-2xl font-black">{MEITI.t('ll_unit', null, 'Unidad')} {i + 1}</h2>
                <p className="font-bold opacity-90">{u.titulo}</p>
                <p className="text-sm opacity-75 mt-1">{u.descripcion}</p>
              </div>

              <div className="flex flex-col items-center gap-6 py-4">
                {lecs.map((l, j) => {
                  const completada = esCompletada(l.id);
                  const idxPrimeraNoCompletada = lecs.findIndex(lx => !esCompletada(lx.id));
                  const esActual = j === idxPrimeraNoCompletada || (idxPrimeraNoCompletada === -1 && j === lecs.length - 1);
                  const bloqueada = !completada && !esActual && j > idxPrimeraNoCompletada;

                  let bg = tema.superficie;
                  let colorIcono = tema.texto;
                  let Icono = Iconos.Lock;
                  let borde = `4px solid ${tema.texto}22`;

                  if (completada) {
                    bg = tema.colorSecundario;
                    colorIcono = '#fff';
                    Icono = Iconos.Check;
                    borde = `4px solid ${tema.colorSecundario}`;
                  } else if (esActual) {
                    bg = tema.colorPrimario;
                    colorIcono = '#fff';
                    Icono = Iconos.Star;
                    borde = `4px solid ${tema.colorPrimario}66`;
                  }

                  const offset = j % 2 === 0 ? '-20px' : '20px';

                  return (
                    <Animacion.motion.button
                      key={l.id}
                      whileTap={!bloqueada ? { scale: 0.9 } : {}}
                      onClick={() => !bloqueada && iniciarLeccion(l)}
                      disabled={bloqueada}
                      className="relative w-20 h-20 rounded-full flex items-center justify-center shadow-lg transition-all"
                      style={{ background: bg, border: borde, transform: `translateX(${offset})`, opacity: bloqueada ? 0.5 : 1 }}
                    >
                      <Icono size={32} color={colorIcono} />
                      {esActual && (
                        <div className="absolute -top-10 bg-white text-black text-xs font-bold px-3 py-1 rounded-xl shadow-md whitespace-nowrap">
                          {MEITI.t('ll_start', null, '¡Empezar!')}
                          <div className="absolute -bottom-1 left-1/2 -translate-x-1/2 w-2 h-2 bg-white rotate-45"></div>
                        </div>
                      )}
                    </Animacion.motion.button>
                  );
                })}
              </div>
            </div>
          );
        })
      )}
    </div>
  );
}

({ datos, tema, UI, MEITI }) => {
  const eco = MEITI.obtenerEcosistemaActual();
  const miId = MEITI.obtenerUsuarioActual();
  const [leccionId, setLeccionId] = useState(null);
  const [ejercicios, setEjercicios] = useState([]);
  const [idxActual, setIdxActual] = useState(0);
  const [respuestaSeleccionada, setRespuestaSeleccionada] = useState('');
  const [estadoFeedback, setEstadoFeedback] = useState(null);
  const [cargando, setCargando] = useState(true);
  const [error, setError] = useState(null);
  const [terminado, setTerminado] = useState(false);

  const [leccionPuntos, setLeccionPuntos] = useState(10);
  const [perfil, setPerfil] = useState(null);

  useEffect(() => {
    const cargar = async () => {
      setCargando(true);
      const resSesion = await MEITI.fetchDatosPropios(`/api/boveda/${MEITI.obtenerTabla('ll_sesion_activa')}?ecosistema=${eco}`);
      if (resSesion.ok && resSesion.registros.length > 0) {
        const lId = resSesion.registros[0].leccion_id;
        setLeccionId(lId);

        const [resEjs, resLec, resPerf] = await Promise.all([
          MEITI.fetchDatos(`/api/boveda/${MEITI.obtenerTabla('ll_ejercicios')}?ecosistema=${eco}`),
          MEITI.fetchDatos(`/api/boveda/${MEITI.obtenerTabla('ll_lecciones')}?ecosistema=${eco}`),
          MEITI.fetchDatosPropios(`/api/boveda/${MEITI.obtenerTabla('ll_perfiles')}?ecosistema=${eco}`)
        ]);

        if (resEjs.ok) {
          setEjercicios(resEjs.registros.filter(e => e.leccion_id === lId).sort((a,b) => a.orden - b.orden));
        }
        if (resLec.ok) {
          const lec = resLec.registros.find(l => l.id === lId);
          if (lec) setLeccionPuntos(lec.puntos || 10);
        }
        if (resPerf.ok && resPerf.registros.length > 0) {
          setPerfil(resPerf.registros[0]);
        }
      } else {
        setError(MEITI.t('ll_no_active_lesson', null, 'No hay lección activa. Vuelve al camino.'));
      }
      setCargando(false);
    };
    cargar();
  }, []);

  const comprobar = () => {
    if (!respuestaSeleccionada) return;
    const ej = ejercicios[idxActual];
    if (respuestaSeleccionada.toLowerCase().trim() === ej.respuesta_correcta.toLowerCase().trim()) {
      setEstadoFeedback('correcta');
    } else {
      setEstadoFeedback('incorrecta');
    }
  };

  const continuar = async () => {
    setEstadoFeedback(null);
    setRespuestaSeleccionada('');
    if (idxActual < ejercicios.length - 1) {
      setIdxActual(idxActual + 1);
    } else {
      finalizarLeccion();
    }
  };

  const finalizarLeccion = async () => {
    setTerminado(true);
    const payloadProgreso = { id: 'prog_' + Date.now(), usuario_id: miId, leccion_id: leccionId, completada: 1, fecha: new Date().toISOString() };

    const mutaciones = [
      { url: `/api/boveda/${MEITI.obtenerTabla('ll_progreso')}?ecosistema=${eco}`, opciones: { method: 'POST', headers: {'Content-Type':'application/json'}, body: JSON.stringify(payloadProgreso) } }
    ];

    if (perfil) {
      const payloadPerfil = { ...perfil, puntos: (perfil.puntos || 0) + leccionPuntos, racha: (perfil.racha || 0) + 1 };
      mutaciones.push({ url: `/api/boveda/${MEITI.obtenerTabla('ll_perfiles')}?ecosistema=${eco}`, opciones: { method: 'PUT', headers: {'Content-Type':'application/json'}, body: JSON.stringify(payloadPerfil) } });
    } else {
      const nuevoPerfil = { id: 'perf_' + miId, usuario_id: miId, estudiante_id: miId, nombre: 'Estudiante', puntos: leccionPuntos, racha: 1 };
      mutaciones.push({ url: `/api/boveda/${MEITI.obtenerTabla('ll_perfiles')}?ecosistema=${eco}`, opciones: { method: 'POST', headers: {'Content-Type':'application/json'}, body: JSON.stringify(nuevoPerfil) } });
    }

    await MEITI.mutarVarias(mutaciones, {
      alLograr: () => {},
      alFallar: () => {}
    });
  };

  if (cargando) return <div className="p-8 text-center"><Iconos.LoaderCircle className="animate-spin mx-auto" size={32} color={tema.colorPrimario} /></div>;
  if (error) return <UI.Aviso mensaje={error} tono="peligro" onCerrar={() => MEITI.irAPagina('camino')} />;
  if (ejercicios.length === 0) return <UI.EstadoVacio icono="fa-book-open" mensaje={MEITI.t('ll_no_exercises', null, 'Esta lección no tiene ejercicios aún.')} />;

  if (terminado) {
    return (
      <div className="flex flex-col items-center justify-center min-h-[70vh] gap-6 text-center px-4">
        <Animacion.motion.div initial={{ scale: 0 }} animate={{ scale: 1 }} transition={{ type: 'spring' }}>
          <Iconos.Trophy size={80} color={tema.colorSecundario} />
        </Animacion.motion.div>
        <h2 className="text-3xl font-black" style={{ color: tema.texto }}>{MEITI.t('ll_lesson_complete', null, '¡Lección Completada!')}</h2>
        <p className="opacity-70" style={{ color: tema.texto }}>{MEITI.t('ll_lesson_complete_desc', null, 'Has ganado puntos de experiencia.')}</p>
        <button onClick={() => MEITI.irAPagina('camino')} className="w-full py-4 rounded-2xl font-black text-lg mt-8" style={{ background: tema.colorPrimario, color: '#fff' }}>
          {MEITI.t('ll_btn_finish', null, 'Continuar')}
        </button>
      </div>
    );
  }

  const ej = ejercicios[idxActual];
  const progresoPct = ((idxActual) / ejercicios.length) * 100;
  let opciones = [];
  try { opciones = JSON.parse(ej.opciones || '[]'); } catch(e) {}

  return (
    <div className="flex flex-col pb-32 px-2">
      <div className="flex items-center gap-4 py-4">
        <button onClick={() => MEITI.irAPagina('camino')}><Iconos.X size={28} color={tema.texto} className="opacity-50" /></button>
        <div className="flex-1 h-4 rounded-full overflow-hidden" style={{ background: tema.texto + '22' }}>
          <div className="h-full transition-all duration-500" style={{ width: `${progresoPct}%`, background: tema.colorSecundario }}></div>
        </div>
      </div>

      <div className="flex-1 flex flex-col justify-center gap-8">
        <h2 className="text-2xl font-bold" style={{ color: tema.texto }}>{ej.pregunta}</h2>

        {ej.tipo === 'opcion_multiple' ? (
          <div className="flex flex-col gap-3">
            {opciones.map((op, i) => (
              <button 
                key={i}
                onClick={() => !estadoFeedback && setRespuestaSeleccionada(op)}
                className="p-4 rounded-2xl border-2 text-left font-bold text-lg transition-all"
                style={{ 
                  borderColor: respuestaSeleccionada === op ? tema.colorPrimario : tema.texto + '22',
                  background: respuestaSeleccionada === op ? tema.colorPrimario + '11' : 'transparent',
                  color: respuestaSeleccionada === op ? tema.colorPrimario : tema.texto
                }}
              >
                {op}
              </button>
            ))}
          </div>
        ) : (
          <UI.Campo 
            tipo="text" 
            valor={respuestaSeleccionada} 
            onChange={e => !estadoFeedback && setRespuestaSeleccionada(e.target.value)} 
            placeholder={MEITI.t('ll_type_answer', null, 'Escribe tu respuesta aquí...')}
          />
        )}
      </div>

      <div className="fixed bottom-0 inset-x-0 p-4 bg-white border-t" style={{ borderColor: tema.texto + '11', background: tema.fondo }}>
        {!estadoFeedback ? (
          <button 
            onClick={comprobar}
            disabled={!respuestaSeleccionada}
            className="w-full py-4 rounded-2xl font-black text-lg transition-opacity"
            style={{ background: tema.colorPrimario, color: '#fff', opacity: respuestaSeleccionada ? 1 : 0.5 }}
          >
            {MEITI.t('ll_btn_check', null, 'Comprobar')}
          </button>
        ) : null}
      </div>

      <Animacion.AnimatePresence>
        {estadoFeedback && (
          <Animacion.motion.div 
            initial={{ y: '100%' }} animate={{ y: 0 }} exit={{ y: '100%' }} transition={{ type: 'spring', damping: 25 }}
            className="fixed bottom-0 inset-x-0 p-6 rounded-t-3xl flex flex-col gap-4 z-50"
            style={{ background: estadoFeedback === 'correcta' ? '#dcfce7' : '#fee2e2' }}
          >
            <div className="flex items-center gap-3">
              <div className="w-10 h-10 rounded-full flex items-center justify-center" style={{ background: estadoFeedback === 'correcta' ? '#16a34a' : '#dc2626', color: '#fff' }}>
                {estadoFeedback === 'correcta' ? <Iconos.Check size={24} /> : <Iconos.X size={24} />}
              </div>
              <h3 className="text-2xl font-black" style={{ color: estadoFeedback === 'correcta' ? '#16a34a' : '#dc2626' }}>
                {estadoFeedback === 'correcta' ? MEITI.t('ll_correct', null, '¡Excelente!') : MEITI.t('ll_incorrect', null, 'Respuesta incorrecta')}
              </h3>
            </div>
            {estadoFeedback === 'incorrecta' && (
              <div className="text-red-800">
                <span className="font-bold">{MEITI.t('ll_correct_answer', null, 'Solución correcta:')}</span> {ej.respuesta_correcta}
              </div>
            )}
            <button 
              onClick={continuar}
              className="w-full py-4 rounded-2xl font-black text-lg"
              style={{ background: estadoFeedback === 'correcta' ? '#16a34a' : '#dc2626', color: '#fff' }}
            >
              {MEITI.t('ll_btn_continue', null, 'Continuar')}
            </button>
          </Animacion.motion.div>
        )}
      </Animacion.AnimatePresence>
    </div>
  );
}

({ datos, tema, UI, MEITI }) => {
  const eco = MEITI.obtenerEcosistemaActual();
  const miId = MEITI.obtenerUsuarioActual();
  const [ranking, setRanking] = useState([]);
  const [cargando, setCargando] = useState(true);
  const [error, setError] = useState(null);

  useEffect(() => {
    const cargar = async () => {
      setCargando(true);
      const res = await MEITI.fetchDatos(`/api/boveda/${MEITI.obtenerTabla('ll_perfiles')}?ecosistema=${eco}`);
      if (res.ok) {
        const ordenados = res.registros.sort((a, b) => (b.puntos || 0) - (a.puntos || 0));
        setRanking(ordenados.map((r, i) => ({ ...r, posicion: i + 1 })));
      } else {
        setError(res.error || MEITI.t('error_loading_ranking', null, 'Error al cargar el ranking'));
      }
      setCargando(false);
    };
    cargar();
  }, []);

  const columnas = [
    {
      clave: 'posicion',
      etiqueta: MEITI.t('col_pos', null, '#'),
      render: (fila) => {
        let colorPos = tema.texto;
        if (fila.posicion === 1) colorPos = '#fbbf24';
        if (fila.posicion === 2) colorPos = '#9ca3af';
        if (fila.posicion === 3) colorPos = '#b45309';
        return (
          <div className="font-black text-lg text-center" style={{ color: colorPos }}>
            {fila.posicion}
          </div>
        );
      }
    },
    {
      clave: 'nombre',
      etiqueta: MEITI.t('col_student', null, 'Estudiante'),
      render: (fila) => {
        const esYo = fila.estudiante_id === miId || fila.usuario_id === miId;
        const avatarIndex = ((fila.posicion - 1) % 35) + 1;
        return (
          <div className="flex items-center gap-3">
            <img 
              src={`http://localhost:4001/avatares/memo_${avatarIndex}.png`} 
              alt="avatar" 
              className="w-10 h-10 rounded-full bg-black/5 object-cover"
            />
            <span className="font-bold" style={{ color: tema.texto }}>
              {fila.nombre || MEITI.t('anonymous_student', null, 'Estudiante')}
            </span>
            {esYo && <UI.Chip tono="exito">{MEITI.t('you_badge', null, 'TÚ')}</UI.Chip>}
          </div>
        );
      }
    },
    {
      clave: 'racha',
      etiqueta: MEITI.t('col_streak', null, 'Racha'),
      render: (fila) => (
        <div className="flex items-center gap-2 text-sm font-medium opacity-80" style={{ color: tema.texto }}>
          <i className="fa-solid fa-fire" style={{ color: tema.colorSecundario }}></i>
          {fila.racha || 0} {MEITI.t('days_streak', null, 'días')}
        </div>
      )
    },
    {
      clave: 'puntos',
      etiqueta: MEITI.t('col_xp', null, 'XP'),
      render: (fila) => (
        <div className="font-black text-lg" style={{ color: tema.colorPrimario }}>
          {fila.puntos || 0} XP
        </div>
      )
    }
  ];

  return (
    <div className="flex flex-col gap-6 flex-1 min-h-0 p-2 md:p-4">
      <div className="flex items-center gap-3">
        <i className="fa-solid fa-trophy text-3xl" style={{ color: tema.colorSecundario }}></i>
        <h1 className="text-2xl font-black" style={{ color: tema.texto }}>
          {MEITI.t('ll_leaderboard_title', null, 'Ranking Semanal')}
        </h1>
      </div>

      <UI.Aviso mensaje={error} tono="peligro" onCerrar={() => setError(null)} />

      <UI.Tarjeta className="flex flex-col flex-1 min-h-0 p-0 overflow-hidden">
        {cargando ? (
          <div className="p-8 flex flex-col items-center justify-center flex-1">
            <i className="fa-solid fa-circle-notch fa-spin text-4xl" style={{ color: tema.colorPrimario }}></i>
            <p className="mt-4 font-medium opacity-70" style={{ color: tema.texto }}>
              {MEITI.t('loading_ranking_msg', null, 'Cargando posiciones...')}
            </p>
          </div>
        ) : ranking.length === 0 ? (
          <div className="p-6 flex-1 flex items-center justify-center">
            <UI.EstadoVacio 
              icono="fa-medal" 
              mensaje={MEITI.t('ll_no_ranking_yet', null, 'Aún no hay estudiantes en el ranking.')} 
            />
          </div>
        ) : (
          <div className="flex-1 min-h-0 flex flex-col">
            <UI.TablaDatos
              columnas={columnas}
              datos={ranking}
              claveId="id"
              advertirAccionIncompleta={false}
            />
          </div>
        )}
      </UI.Tarjeta>
    </div>
  );
}

({ datos, tema, UI, MEITI }) => {
  const eco = MEITI.obtenerEcosistemaActual();
  const [pestana, setPestana] = useState('unidades');
  const [unidades, setUnidades] = useState([]);
  const [lecciones, setLecciones] = useState([]);
  const [ejercicios, setEjercicios] = useState([]);
  const [catalogos, setCatalogos] = useState([]);
  const [error, setError] = useState(null);

  const [formU, setFormU] = useState({ id: '', titulo: '', descripcion: '', orden: '' });
  const [formL, setFormL] = useState({ id: '', unidad_id: '', titulo: '', orden: '', puntos: '10' });
  const [formE, setFormE] = useState({ id: '', leccion_id: '', tipo: '', pregunta: '', opciones: '', respuesta_correcta: '', orden: '' });

  const cargar = async () => {
    const [resU, resL, resE, resC] = await Promise.all([
      MEITI.fetchDatos(`/api/boveda/${MEITI.obtenerTabla('ll_unidades')}?ecosistema=${eco}`),
      MEITI.fetchDatos(`/api/boveda/${MEITI.obtenerTabla('ll_lecciones')}?ecosistema=${eco}`),
      MEITI.fetchDatos(`/api/boveda/${MEITI.obtenerTabla('ll_ejercicios')}?ecosistema=${eco}`),
      MEITI.fetchDatos(`/api/boveda/${MEITI.obtenerTabla('ll_catalogos')}?ecosistema=${eco}`)
    ]);
    if (resU.ok) setUnidades(resU.registros);
    if (resL.ok) setLecciones(resL.registros);
    if (resE.ok) setEjercicios(resE.registros);
    if (resC.ok) setCatalogos(resC.registros);
  };

  useEffect(() => { cargar(); }, []);

  if (MEITI.miRolEnLaApp() !== 'admin' && !MEITI.soyDuenoDeLaApp()) {
    return <UI.Aviso tono="peligro" mensaje={MEITI.t('ll_admin_only', null, 'Acceso denegado. Solo profesores.')} />;
  }

  const tiposEjercicio = catalogos.filter(c => c.tipo === 'tipo_ejercicio');

  const guardarUnidad = async (e) => {
    e.preventDefault();
    const payload = { id: formU.id || 'uni_' + Date.now(), titulo: formU.titulo, descripcion: formU.descripcion, orden: Number(formU.orden) || 1 };
    await MEITI.mutar(`/api/boveda/${MEITI.obtenerTabla('ll_unidades')}?ecosistema=${eco}`, { method: formU.id ? 'PUT' : 'POST', headers: {'Content-Type':'application/json'}, body: JSON.stringify(payload) }, { alLograr: () => { setFormU({id:'', titulo:'', descripcion:'', orden:''}); cargar(); }, alFallar: setError });
  };

  const borrarUnidad = async (id) => {
    if (!await MEITI.confirmar(MEITI.t('ll_del_unit', null, '¿Borrar unidad?'), { titulo: MEITI.t('delete', null, 'Borrar'), confirmar: MEITI.t('delete_yes', null, 'Sí, borrar'), tono: 'peligro' })) return;
    await MEITI.mutar(`/api/boveda/${MEITI.obtenerTabla('ll_unidades')}?ecosistema=${eco}&id=${id}`, { method: 'DELETE' }, { alLograr: cargar, alFallar: setError });
  };

  const guardarLeccion = async (e) => {
    e.preventDefault();
    const payload = { id: formL.id || 'lec_' + Date.now(), unidad_id: formL.unidad_id, titulo: formL.titulo, orden: Number(formL.orden) || 1, puntos: Number(formL.puntos) || 10 };
    await MEITI.mutar(`/api/boveda/${MEITI.obtenerTabla('ll_lecciones')}?ecosistema=${eco}`, { method: formL.id ? 'PUT' : 'POST', headers: {'Content-Type':'application/json'}, body: JSON.stringify(payload) }, { alLograr: () => { setFormL({id:'', unidad_id:'', titulo:'', orden:'', puntos:'10'}); cargar(); }, alFallar: setError });
  };

  const borrarLeccion = async (id) => {
    if (!await MEITI.confirmar(MEITI.t('ll_del_lesson', null, '¿Borrar lección?'), { titulo: MEITI.t('delete', null, 'Borrar'), confirmar: MEITI.t('delete_yes', null, 'Sí, borrar'), tono: 'peligro' })) return;
    await MEITI.mutar(`/api/boveda/${MEITI.obtenerTabla('ll_lecciones')}?ecosistema=${eco}&id=${id}`, { method: 'DELETE' }, { alLograr: cargar, alFallar: setError });
  };

  const guardarEjercicio = async (e) => {
    e.preventDefault();
    let opcionesJSON = formE.opciones;
    if (formE.tipo === 'opcion_multiple' && formE.opciones && !formE.opciones.trim().startsWith('[')) {
      opcionesJSON = JSON.stringify(formE.opciones.split(',').map(s => s.trim()));
    }
    const payload = { id: formE.id || 'ej_' + Date.now(), leccion_id: formE.leccion_id, tipo: formE.tipo, pregunta: formE.pregunta, opciones: opcionesJSON, respuesta_correcta: formE.respuesta_correcta, orden: Number(formE.orden) || 1 };
    await MEITI.mutar(`/api/boveda/${MEITI.obtenerTabla('ll_ejercicios')}?ecosistema=${eco}`, { method: formE.id ? 'PUT' : 'POST', headers: {'Content-Type':'application/json'}, body: JSON.stringify(payload) }, { alLograr: () => { setFormE({id:'', leccion_id:'', tipo:'', pregunta:'', opciones:'', respuesta_correcta:'', orden:''}); cargar(); }, alFallar: setError });
  };

  const borrarEjercicio = async (id) => {
    if (!await MEITI.confirmar(MEITI.t('ll_del_exercise', null, '¿Borrar ejercicio?'), { titulo: MEITI.t('delete', null, 'Borrar'), confirmar: MEITI.t('delete_yes', null, 'Sí, borrar'), tono: 'peligro' })) return;
    await MEITI.mutar(`/api/boveda/${MEITI.obtenerTabla('ll_ejercicios')}?ecosistema=${eco}&id=${id}`, { method: 'DELETE' }, { alLograr: cargar, alFallar: setError });
  };

  return (
    <div className="flex flex-col gap-6 pb-28 flex-1 min-h-0">
      <UI.Pestanas 
        pestanas={[
          {id:'unidades', titulo: MEITI.t('ll_units', null, 'Unidades')}, 
          {id:'lecciones', titulo: MEITI.t('ll_lessons', null, 'Lecciones')},
          {id:'ejercicios', titulo: MEITI.t('ll_exercises', null, 'Ejercicios')}
        ]}
        activa={pestana}
        onCambio={setPestana}
      />
      <UI.Aviso mensaje={error} tono="peligro" onCerrar={() => setError(null)} />

      {pestana === 'unidades' && (
        <div className="flex flex-col gap-6 flex-1 min-h-0">
          <UI.Tarjeta>
            <UI.Etiqueta>{formU.id ? MEITI.t('ll_edit_unit', null, 'Editar Unidad') : MEITI.t('ll_new_unit', null, 'Nueva Unidad')}</UI.Etiqueta>
            <form onSubmit={guardarUnidad} className="flex flex-col gap-4 mt-2">
              <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                <div className="flex-1"><UI.Campo etiqueta={MEITI.t('ll_title', null, 'Título')} tipo="text" valor={formU.titulo} onChange={e => setFormU({...formU, titulo: e.target.value})} /></div>
                <div className="flex-1"><UI.Campo etiqueta={MEITI.t('ll_order', null, 'Orden')} tipo="number" valor={formU.orden} onChange={e => setFormU({...formU, orden: e.target.value})} /></div>
                <div className="md:col-span-2 flex-1"><UI.Campo etiqueta={MEITI.t('ll_desc', null, 'Descripción')} tipo="text" valor={formU.descripcion} onChange={e => setFormU({...formU, descripcion: e.target.value})} /></div>
              </div>
              <div className="flex gap-2">
                <UI.Boton tipo="submit" variante="primario">{MEITI.t('ll_save', null, 'Guardar')}</UI.Boton>
                {formU.id && <UI.Boton tipo="button" variante="secundario" onClick={() => setFormU({id:'', titulo:'', descripcion:'', orden:''})}>{MEITI.t('ll_cancel', null, 'Cancelar')}</UI.Boton>}
              </div>
            </form>
          </UI.Tarjeta>
          <UI.Tarjeta className="flex flex-col flex-1 min-h-0">
            <div className="flex-1 overflow-y-auto min-h-0">
              <UI.TablaDatos 
                columnas={[{clave:'orden', etiqueta: MEITI.t('ll_order_col', null, '#')}, {clave:'titulo', etiqueta: MEITI.t('ll_title_col', null, 'Título')}]}
                datos={unidades}
                claveId="id"
                onEditar={f => setFormU({id: f.id, titulo: f.titulo, descripcion: f.descripcion, orden: f.orden})}
                onBorrar={f => borrarUnidad(f.id)}
              />
            </div>
          </UI.Tarjeta>
        </div>
      )}

      {pestana === 'lecciones' && (
        <div className="flex flex-col gap-6 flex-1 min-h-0">
          <UI.Tarjeta>
            <UI.Etiqueta>{formL.id ? MEITI.t('ll_edit_lesson', null, 'Editar Lección') : MEITI.t('ll_new_lesson', null, 'Nueva Lección')}</UI.Etiqueta>
            <form onSubmit={guardarLeccion} className="flex flex-col gap-4 mt-2">
              <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                <div className="flex-1"><UI.Campo etiqueta={MEITI.t('ll_unit', null, 'Unidad')} tipo="select" valor={formL.unidad_id} onChange={e => setFormL({...formL, unidad_id: e.target.value})} opciones={[{value:'', label: MEITI.t('ll_select', null, 'Seleccionar...')}, ...unidades.map(u => ({value: u.id, label: u.titulo}))]} /></div>
                <div className="flex-1"><UI.Campo etiqueta={MEITI.t('ll_title', null, 'Título')} tipo="text" valor={formL.titulo} onChange={e => setFormL({...formL, titulo: e.target.value})} /></div>
                <div className="flex-1"><UI.Campo etiqueta={MEITI.t('ll_order', null, 'Orden')} tipo="number" valor={formL.orden} onChange={e => setFormL({...formL, orden: e.target.value})} /></div>
                <div className="flex-1"><UI.Campo etiqueta={MEITI.t('ll_points', null, 'Puntos')} tipo="number" valor={formL.puntos} onChange={e => setFormL({...formL, puntos: e.target.value})} /></div>
              </div>
              <div className="flex gap-2">
                <UI.Boton tipo="submit" variante="primario">{MEITI.t('ll_save', null, 'Guardar')}</UI.Boton>
                {formL.id && <UI.Boton tipo="button" variante="secundario" onClick={() => setFormL({id:'', unidad_id:'', titulo:'', orden:'', puntos:'10'})}>{MEITI.t('ll_cancel', null, 'Cancelar')}</UI.Boton>}
              </div>
            </form>
          </UI.Tarjeta>
          <UI.Tarjeta className="flex flex-col flex-1 min-h-0">
            <div className="flex-1 overflow-y-auto min-h-0">
              <UI.TablaDatos 
                columnas={[{clave:'titulo', etiqueta: MEITI.t('ll_lesson_col', null, 'Lección')}, {clave:'unidad_id', etiqueta: MEITI.t('ll_unit_col', null, 'Unidad'), render: f => unidades.find(u => u.id === f.unidad_id)?.titulo || '---'}]}
                datos={lecciones}
                claveId="id"
                onEditar={f => setFormL({id: f.id, unidad_id: f.unidad_id, titulo: f.titulo, orden: f.orden, puntos: f.puntos})}
                onBorrar={f => borrarLeccion(f.id)}
              />
            </div>
          </UI.Tarjeta>
        </div>
      )}

      {pestana === 'ejercicios' && (
        <div className="flex flex-col gap-6 flex-1 min-h-0">
          <UI.Tarjeta>
            <UI.Etiqueta>{formE.id ? MEITI.t('ll_edit_exercise', null, 'Editar Ejercicio') : MEITI.t('ll_new_exercise', null, 'Nuevo Ejercicio')}</UI.Etiqueta>
            <form onSubmit={guardarEjercicio} className="flex flex-col gap-4 mt-2">
              <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                <div className="flex-1"><UI.Campo etiqueta={MEITI.t('ll_lesson', null, 'Lección')} tipo="select" valor={formE.leccion_id} onChange={e => setFormE({...formE, leccion_id: e.target.value})} opciones={[{value:'', label: MEITI.t('ll_select', null, 'Seleccionar...')}, ...lecciones.map(l => ({value: l.id, label: l.titulo}))]} /></div>
                <div className="flex-1"><UI.Campo etiqueta={MEITI.t('ll_type', null, 'Tipo')} tipo="select" valor={formE.tipo} onChange={e => setFormE({...formE, tipo: e.target.value})} opciones={[{value:'', label: MEITI.t('ll_select', null, 'Seleccionar...')}, ...tiposEjercicio.map(t => ({value: t.clave, label: t.etiqueta}))]} /></div>
                <div className="md:col-span-2 flex-1"><UI.Campo etiqueta={MEITI.t('ll_question', null, 'Pregunta')} tipo="text" valor={formE.pregunta} onChange={e => setFormE({...formE, pregunta: e.target.value})} /></div>
                {formE.tipo === 'opcion_multiple' && (
                  <div className="md:col-span-2 flex-1"><UI.Campo etiqueta={MEITI.t('ll_options', null, 'Opciones (separadas por coma)')} tipo="text" valor={formE.opciones} onChange={e => setFormE({...formE, opciones: e.target.value})} placeholder={MEITI.t('ll_options_ph', null, 'Ej: Gato, Perro, Pájaro')} /></div>
                )}
                <div className="flex-1"><UI.Campo etiqueta={MEITI.t('ll_correct_answer', null, 'Respuesta Correcta')} tipo="text" valor={formE.respuesta_correcta} onChange={e => setFormE({...formE, respuesta_correcta: e.target.value})} /></div>
                <div className="flex-1"><UI.Campo etiqueta={MEITI.t('ll_order', null, 'Orden')} tipo="number" valor={formE.orden} onChange={e => setFormE({...formE, orden: e.target.value})} /></div>
              </div>
              <div className="flex gap-2">
                <UI.Boton tipo="submit" variante="primario">{MEITI.t('ll_save', null, 'Guardar')}</UI.Boton>
                {formE.id && <UI.Boton tipo="button" variante="secundario" onClick={() => setFormE({id:'', leccion_id:'', tipo:'', pregunta:'', opciones:'', respuesta_correcta:'', orden:''})}>{MEITI.t('ll_cancel', null, 'Cancelar')}</UI.Boton>}
              </div>
            </form>
          </UI.Tarjeta>
          <UI.Tarjeta className="flex flex-col flex-1 min-h-0">
            <div className="flex-1 overflow-y-auto min-h-0">
              <UI.TablaDatos 
                columnas={[
                  {clave:'pregunta', etiqueta: MEITI.t('ll_question_col', null, 'Pregunta')}, 
                  {clave:'leccion_id', etiqueta: MEITI.t('ll_lesson_col', null, 'Lección'), render: f => lecciones.find(l => l.id === f.leccion_id)?.titulo || '---'},
                  {clave:'tipo', etiqueta: MEITI.t('ll_type_col', null, 'Tipo'), render: f => tiposEjercicio.find(t => t.clave === f.tipo)?.etiqueta || f.tipo}
                ]}
                datos={ejercicios}
                claveId="id"
                onEditar={f => {
                  let ops = f.opciones;
                  try {
                    const parsed = JSON.parse(f.opciones);
                    if (Array.isArray(parsed)) ops = parsed.join(', ');
                  } catch(e) {}
                  setFormE({id: f.id, leccion_id: f.leccion_id, tipo: f.tipo, pregunta: f.pregunta, opciones: ops || '', respuesta_correcta: f.respuesta_correcta, orden: f.orden});
                }}
                onBorrar={f => borrarEjercicio(f.id)}
              />
            </div>
          </UI.Tarjeta>
        </div>
      )}
    </div>
  );
}

({ datos, tema, UI, MEITI }) => {
  const eco = MEITI.obtenerEcosistemaActual();
  const [perfiles, setPerfiles] = useState([]);
  const [progreso, setProgreso] = useState([]);
  const [cargando, setCargando] = useState(true);
  const [error, setError] = useState(null);

  useEffect(() => {
    const cargar = async () => {
      setCargando(true);
      const [resPerf, resProg] = await Promise.all([
        MEITI.fetchDatosPropios(`/api/boveda/${MEITI.obtenerTabla('ll_perfiles')}?ecosistema=${eco}`),
        MEITI.fetchDatosPropios(`/api/boveda/${MEITI.obtenerTabla('ll_progreso')}?ecosistema=${eco}`)
      ]);

      if (!resPerf.ok || !resProg.ok) {
        setError(MEITI.t('err_load_metrics', null, 'Error al cargar las métricas.'));
      } else {
        setPerfiles(resPerf.registros || []);
        setProgreso(resProg.registros || []);
      }
      setCargando(false);
    };
    cargar();
  }, []);

  if (cargando) return <UI.Tarjeta><div className="p-8 text-center"><Iconos.LoaderCircle className="animate-spin mx-auto mb-2" size={32} color={tema.colorPrimario} /><p style={{color: tema.texto}}>{MEITI.t('loading_metrics', null, 'Calculando métricas...')}</p></div></UI.Tarjeta>;

  const totalAlumnos = perfiles.length;
  const leccionesCompletadas = progreso.filter(p => String(p.completada) === '1').length;
  const rachaPromedio = totalAlumnos > 0 ? (perfiles.reduce((acc, p) => acc + (Number(p.racha) || 0), 0) / totalAlumnos).toFixed(1) : 0;

  const hoy = new Date();
  const ultimos7Dias = Array.from({length: 7}, (_, i) => {
    const d = new Date(hoy);
    d.setDate(d.getDate() - (6 - i));
    return d.toISOString().split('T')[0];
  });

  const datosGrafico = ultimos7Dias.map(fecha => {
    const completadasEseDia = progreso.filter(p => String(p.completada) === '1' && (p.fecha || '').startsWith(fecha)).length;
    return {
      fecha: fecha.split('-').slice(1).join('/'),
      completadas: completadasEseDia
    };
  });

  return (
    <div className="flex flex-col gap-6">
      <UI.Aviso mensaje={error} tono="peligro" onCerrar={() => setError(null)} />

      <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
        <Animacion.motion.div initial={{ opacity: 0, y: 10 }} animate={{ opacity: 1, y: 0 }} transition={{ duration: 0.3 }}>
          <UI.Tarjeta className="flex items-center gap-4 p-6">
            <div className="w-14 h-14 rounded-2xl flex items-center justify-center" style={{ backgroundColor: tema.colorPrimario + '22', color: tema.colorPrimario }}>
              <Iconos.Users size={28} />
            </div>
            <div>
              <p className="text-sm font-bold uppercase tracking-wider opacity-70" style={{ color: tema.texto }}>{MEITI.t('total_students', null, 'Total Alumnos')}</p>
              <p className="text-3xl font-black" style={{ color: tema.texto }}>{totalAlumnos}</p>
            </div>
          </UI.Tarjeta>
        </Animacion.motion.div>

        <Animacion.motion.div initial={{ opacity: 0, y: 10 }} animate={{ opacity: 1, y: 0 }} transition={{ duration: 0.3, delay: 0.1 }}>
          <UI.Tarjeta className="flex items-center gap-4 p-6">
            <div className="w-14 h-14 rounded-2xl flex items-center justify-center" style={{ backgroundColor: tema.colorSecundario + '22', color: tema.colorSecundario }}>
              <Iconos.BookOpenCheck size={28} />
            </div>
            <div>
              <p className="text-sm font-bold uppercase tracking-wider opacity-70" style={{ color: tema.texto }}>{MEITI.t('lessons_done', null, 'Lecciones Completadas')}</p>
              <p className="text-3xl font-black" style={{ color: tema.texto }}>{leccionesCompletadas}</p>
            </div>
          </UI.Tarjeta>
        </Animacion.motion.div>

        <Animacion.motion.div initial={{ opacity: 0, y: 10 }} animate={{ opacity: 1, y: 0 }} transition={{ duration: 0.3, delay: 0.2 }}>
          <UI.Tarjeta className="flex items-center gap-4 p-6">
            <div className="w-14 h-14 rounded-2xl flex items-center justify-center" style={{ backgroundColor: '#f59e0b22', color: '#f59e0b' }}>
              <Iconos.Flame size={28} />
            </div>
            <div>
              <p className="text-sm font-bold uppercase tracking-wider opacity-70" style={{ color: tema.texto }}>{MEITI.t('avg_streak', null, 'Racha Promedio')}</p>
              <p className="text-3xl font-black" style={{ color: tema.texto }}>{rachaPromedio} <span className="text-base font-normal opacity-70">{MEITI.t('days', null, 'días')}</span></p>
            </div>
          </UI.Tarjeta>
        </Animacion.motion.div>
      </div>

      <Animacion.motion.div initial={{ opacity: 0, y: 10 }} animate={{ opacity: 1, y: 0 }} transition={{ duration: 0.3, delay: 0.3 }}>
        <UI.Tarjeta className="flex flex-col gap-4">
          <div className="flex items-center gap-2">
            <Iconos.TrendingUp size={20} color={tema.colorPrimario} />
            <UI.Etiqueta>{MEITI.t('activity_7d', null, 'Actividad (Últimos 7 días)')}</UI.Etiqueta>
          </div>
          {progreso.length === 0 ? (
            <UI.EstadoVacio icono="fa-chart-bar" mensaje={MEITI.t('no_activity_data', null, 'No hay datos de actividad para graficar.')} />
          ) : (
            <div className="w-full h-64">
              <Graficos.ResponsiveContainer width="100%" height="100%">
                <Graficos.BarChart data={datosGrafico}>
                  <Graficos.CartesianGrid strokeDasharray="3 3" stroke={tema.texto + '22'} vertical={false} />
                  <Graficos.XAxis dataKey="fecha" stroke={tema.texto} opacity={0.7} fontSize={12} tickLine={false} axisLine={false} />
                  <Graficos.YAxis stroke={tema.texto} opacity={0.7} fontSize={12} tickLine={false} axisLine={false} />
                  <Graficos.Tooltip 
                    contentStyle={{ backgroundColor: tema.superficie, borderColor: tema.colorPrimario + '44', color: tema.texto, borderRadius: '0.5rem' }}
                    itemStyle={{ color: tema.colorPrimario, fontWeight: 'bold' }}
                  />
                  <Graficos.Bar dataKey="completadas" name={MEITI.t('lessons', null, 'Lecciones')} fill={tema.colorPrimario} radius={[4, 4, 0, 0]} />
                </Graficos.BarChart>
              </Graficos.ResponsiveContainer>
            </div>
          )}
        </UI.Tarjeta>
      </Animacion.motion.div>
    </div>
  );
}

({ datos, tema, UI, MEITI }) => {
  const eco = MEITI.obtenerEcosistemaActual();
  const [alumnos, setAlumnos] = useState([]);
  const [cargando, setCargando] = useState(true);
  const [error, setError] = useState(null);

  useEffect(() => {
    const cargar = async () => {
      setCargando(true);
      const [resPerf, resProg, resLec] = await Promise.all([
        MEITI.fetchDatosPropios(`/api/boveda/${MEITI.obtenerTabla('ll_perfiles')}?ecosistema=${eco}`),
        MEITI.fetchDatosPropios(`/api/boveda/${MEITI.obtenerTabla('ll_progreso')}?ecosistema=${eco}`),
        MEITI.fetchDatos(`/api/boveda/${MEITI.obtenerTabla('ll_lecciones')}?ecosistema=${eco}`)
      ]);

      if (!resPerf.ok || !resProg.ok || !resLec.ok) {
        setError(MEITI.t('err_load_students', null, 'Error al cargar la lista de estudiantes.'));
      } else {
        const perfiles = resPerf.registros || [];
        const progreso = resProg.registros || [];
        const totalLecciones = (resLec.registros || []).length;

        const datosProcesados = perfiles.map(p => {
          const progUsuario = progreso.filter(pr => pr.usuario_id === p.usuario_id && String(pr.completada) === '1');
          const ultima = progUsuario.length > 0 
            ? progUsuario.sort((a, b) => new Date(b.fecha) - new Date(a.fecha))[0].fecha 
            : null;
          const avancePct = totalLecciones > 0 ? Math.min(100, Math.round((progUsuario.length / totalLecciones) * 100)) : 0;

          return {
            ...p,
            lecciones_completadas: progUsuario.length,
            ultima_practica: ultima,
            avance_pct: avancePct
          };
        });

        setAlumnos(datosProcesados.sort((a, b) => b.avance_pct - a.avance_pct));
      }
      setCargando(false);
    };
    cargar();
  }, []);

  const columnas = [
    {
      clave: 'nombre',
      etiqueta: MEITI.t('col_student', null, 'Estudiante'),
      render: (f) => (
        <div className="flex items-center gap-3">
          <div className="w-8 h-8 rounded-full flex items-center justify-center font-bold text-xs" style={{ backgroundColor: tema.colorPrimario + '33', color: tema.colorPrimario }}>
            {(f.nombre || '?').charAt(0).toUpperCase()}
          </div>
          <span className="font-bold" style={{ color: tema.texto }}>{f.nombre || MEITI.t('unnamed', null, 'Sin nombre')}</span>
        </div>
      )
    },
    {
      clave: 'avance_pct',
      etiqueta: MEITI.t('col_progress', null, 'Avance del Curso'),
      render: (f) => (
        <div className="flex items-center gap-3 w-full max-w-[200px]">
          <span className="text-sm font-mono font-bold w-10 text-right" style={{ color: tema.texto }}>{f.avance_pct}%</span>
          <div className="flex-1 h-2 rounded-full overflow-hidden" style={{ backgroundColor: tema.texto + '22' }}>
            <div className="h-full rounded-full transition-all duration-500" style={{ width: `${f.avance_pct}%`, backgroundColor: f.avance_pct === 100 ? '#10b981' : tema.colorPrimario }} />
          </div>
        </div>
      )
    },
    {
      clave: 'racha',
      etiqueta: MEITI.t('col_streak', null, 'Racha'),
      render: (f) => (
        <div className="flex items-center gap-1 font-bold" style={{ color: Number(f.racha) > 0 ? '#f59e0b' : tema.texto, opacity: Number(f.racha) > 0 ? 1 : 0.5 }}>
          <Iconos.Flame size={16} />
          <span>{f.racha || 0}</span>
        </div>
      )
    },
    {
      clave: 'puntos',
      etiqueta: MEITI.t('col_points', null, 'Puntos XP'),
      tipo: 'numero'
    },
    {
      clave: 'ultima_practica',
      etiqueta: MEITI.t('col_last_seen', null, 'Última Práctica'),
      render: (f) => f.ultima_practica ? <span className="text-sm opacity-80" style={{ color: tema.texto }}>{new Date(f.ultima_practica).toLocaleDateString()}</span> : <span className="text-sm opacity-50" style={{ color: tema.texto }}>{MEITI.t('never', null, 'Nunca')}</span>
    }
  ];

  return (
    <Animacion.motion.div initial={{ opacity: 0, y: 10 }} animate={{ opacity: 1, y: 0 }} transition={{ duration: 0.3, delay: 0.4 }}>
      <UI.Tarjeta className="flex flex-col gap-4">
        <div className="flex items-center gap-2">
          <Iconos.ListChecks size={20} color={tema.colorSecundario} />
          <UI.Etiqueta>{MEITI.t('students_list', null, 'Lista de Estudiantes')}</UI.Etiqueta>
        </div>

        <UI.Aviso mensaje={error} tono="peligro" onCerrar={() => setError(null)} />

        {cargando ? (
          <div className="p-8 text-center">
            <Iconos.LoaderCircle className="animate-spin mx-auto mb-2" size={32} color={tema.colorSecundario} />
            <p style={{color: tema.texto}}>{MEITI.t('loading_students', null, 'Cargando estudiantes...')}</p>
          </div>
        ) : alumnos.length === 0 ? (
          <UI.EstadoVacio icono="fa-users-slash" mensaje={MEITI.t('no_students', null, 'Todavía no hay estudiantes registrados.')} />
        ) : (
          <UI.TablaDatos 
            columnas={columnas} 
            datos={alumnos} 
            claveId="usuario_id" 
            advertirAccionIncompleta={false}
          />
        )}
      </UI.Tarjeta>
    </Animacion.motion.div>
  );
}

({ datos, tema, UI, MEITI }) => {
  const eco = MEITI.obtenerEcosistemaActual();
  const tabla = MEITI.obtenerTabla('ll_catalogos');

  const [catalogos, setCatalogos] = useState([]);
  const [cargando, setCargando] = useState(true);
  const [guardando, setGuardando] = useState(false);
  const [error, setError] = useState(null);
  const [exito, setExito] = useState(null);
  const [pestana, setPestana] = useState('nivel');

  const vacio = { id: '', clave: '', etiqueta: '' };
  const [form, setForm] = useState(vacio);

  const esAdmin = MEITI.miRolEnLaApp() === 'admin' || MEITI.soyDuenoDeLaApp();

  const cargar = async () => {
    setCargando(true);
    const res = await MEITI.fetchDatos(`/api/boveda/${tabla}?ecosistema=${eco}`);
    if (res.ok) {
      setCatalogos(res.registros || []);
    } else {
      setError(res.error || MEITI.t('err_load_catalogs', null, 'Error al cargar los catálogos.'));
    }
    setCargando(false);
  };

  useEffect(() => {
    if (esAdmin) cargar();
  }, [esAdmin]);

  if (!esAdmin) {
    return <UI.Aviso tono="peligro" mensaje={MEITI.t('admin_only', null, 'Esta sección es solo para administradores.')} />;
  }

  const guardar = async (e) => {
    e.preventDefault();
    setError(null);
    setExito(null);

    if (!form.clave.trim() || !form.etiqueta.trim()) {
      setError(MEITI.t('err_empty_fields', null, 'La clave y la etiqueta son obligatorias.'));
      return;
    }

    setGuardando(true);
    const esNuevo = !form.id;
    const payload = {
      id: esNuevo ? `cat_${Date.now()}` : form.id,
      tipo: pestana,
      clave: form.clave.trim(),
      etiqueta: form.etiqueta.trim()
    };

    await MEITI.mutar(`/api/boveda/${tabla}?ecosistema=${eco}`, {
      method: esNuevo ? 'POST' : 'PUT',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify(payload)
    }, {
      alLograr: () => {
        setExito(MEITI.t('success_saved', null, 'Registro guardado correctamente.'));
        setForm(vacio);
        cargar();
        setGuardando(false);
      },
      alFallar: (err) => {
        setError(err || MEITI.t('err_save', null, 'Error al guardar el registro.'));
        setGuardando(false);
      }
    });
  };

  const borrar = async (id) => {
    if (!await MEITI.confirmar(MEITI.t('confirm_delete_cat', null, '¿Borrar este registro del catálogo?'), { titulo: MEITI.t('delete', null, 'Borrar'), confirmar: MEITI.t('yes_delete', null, 'Sí, borrar'), tono: 'peligro' })) return;

    setError(null);
    setExito(null);

    await MEITI.mutar(`/api/boveda/${tabla}?ecosistema=${eco}&id=${id}`, {
      method: 'DELETE'
    }, {
      alLograr: () => {
        setExito(MEITI.t('success_deleted', null, 'Registro eliminado.'));
        if (form.id === id) setForm(vacio);
        cargar();
      },
      alFallar: (err) => setError(err || MEITI.t('err_delete', null, 'Error al eliminar el registro.'))
    });
  };

  const editar = (fila) => {
    setForm({ id: fila.id, clave: fila.clave || '', etiqueta: fila.etiqueta || '' });
    window.scrollTo({ top: 0, behavior: 'smooth' });
  };

  const cambiarPestana = (p) => {
    setPestana(p);
    setForm(vacio);
    setError(null);
    setExito(null);
  };

  const filtrados = catalogos.filter(c => c.tipo === pestana);

  const columnas = [
    { clave: 'clave', etiqueta: MEITI.t('col_key', null, 'Clave Interna') },
    { clave: 'etiqueta', etiqueta: MEITI.t('col_label', null, 'Etiqueta Visible') }
  ];

  const pestanasDef = [
    { id: 'nivel', titulo: MEITI.t('tab_levels', null, 'Niveles de Idioma'), icono: 'fa-layer-group' },
    { id: 'tipo_ejercicio', titulo: MEITI.t('tab_exercises', null, 'Tipos de Ejercicio'), icono: 'fa-dumbbell' }
  ];

  return (
    <div className="flex flex-col gap-6 pb-28">
      <UI.Pestanas pestanas={pestanasDef} activa={pestana} onCambio={cambiarPestana} />

      <Animacion.motion.div initial={{ opacity: 0, y: 10 }} animate={{ opacity: 1, y: 0 }} transition={{ duration: 0.3 }} key={`form-${pestana}`}>
        <UI.Tarjeta>
          <div className="flex items-center gap-2 mb-4">
            <Iconos.Tags size={20} color={tema.colorPrimario} />
            <UI.Etiqueta>{form.id ? MEITI.t('edit_record', null, 'Editar Registro') : MEITI.t('new_record', null, 'Nuevo Registro')}</UI.Etiqueta>
          </div>

          <UI.Aviso mensaje={error} tono="peligro" onCerrar={() => setError(null)} />
          <UI.Aviso mensaje={exito} tono="exito" onCerrar={() => setExito(null)} />

          <form onSubmit={guardar} className="flex flex-col gap-4">
            <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
              <div className="flex-1">
                <UI.Campo 
                  etiqueta={MEITI.t('f_key', null, 'Clave Interna (sin espacios)')} 
                  tipo="text" 
                  valor={form.clave} 
                  onChange={e => setForm({...form, clave: e.target.value})} 
                  placeholder={pestana === 'nivel' ? 'ej: a1, b2, c1' : 'ej: multiple_choice, fill_blanks'} 
                />
              </div>
              <div className="flex-1">
                <UI.Campo 
                  etiqueta={MEITI.t('f_label', null, 'Etiqueta Visible')} 
                  tipo="text" 
                  valor={form.etiqueta} 
                  onChange={e => setForm({...form, etiqueta: e.target.value})} 
                  placeholder={pestana === 'nivel' ? 'ej: Principiante (A1)' : 'ej: Opción Múltiple'} 
                />
              </div>
            </div>
            <div className="flex gap-2 mt-2">
              <UI.Boton tipo="submit" variante="primario" disabled={guardando}>
                <span className="flex items-center gap-2">
                  <Iconos.Save size={16} /> 
                  {guardando ? MEITI.t('saving', null, 'Guardando...') : (form.id ? MEITI.t('btn_update', null, 'Actualizar') : MEITI.t('btn_create', null, 'Crear Registro'))}
                </span>
              </UI.Boton>
              {form.id && (
                <UI.Boton tipo="button" variante="secundario" onClick={() => setForm(vacio)}>
                  <span className="flex items-center gap-2"><Iconos.X size={16} /> {MEITI.t('btn_cancel', null, 'Cancelar')}</span>
                </UI.Boton>
              )}
            </div>
          </form>
        </UI.Tarjeta>
      </Animacion.motion.div>

      <Animacion.motion.div initial={{ opacity: 0, y: 10 }} animate={{ opacity: 1, y: 0 }} transition={{ duration: 0.3, delay: 0.1 }} key={`list-${pestana}`}>
        <UI.Tarjeta className="flex flex-col gap-4">
          <div className="flex items-center gap-2">
            <Iconos.List size={20} color={tema.colorSecundario} />
            <UI.Etiqueta>{MEITI.t('records_list', null, 'Registros Actuales')}</UI.Etiqueta>
          </div>

          {cargando ? (
            <div className="p-8 text-center">
              <Iconos.LoaderCircle className="animate-spin mx-auto mb-2" size={32} color={tema.colorSecundario} />
              <p style={{color: tema.texto}}>{MEITI.t('loading', null, 'Cargando...')}</p>
            </div>
          ) : filtrados.length === 0 ? (
            <UI.EstadoVacio icono="fa-tags" mensaje={MEITI.t('empty_catalog', null, 'No hay registros en esta categoría todavía.')} />
          ) : (
            <UI.TablaDatos 
              columnas={columnas} 
              datos={filtrados} 
              claveId="id" 
              onEditar={editar} 
              onBorrar={(fila) => borrar(fila.id)} 
            />
          )}
        </UI.Tarjeta>
      </Animacion.motion.div>
    </div>
  );
}

({ datos, tema, UI, MEITI }) => {
  const eco = MEITI.obtenerEcosistemaActual();
  const base = '/api/boveda/' + MEITI.obtenerTabla('configuracion_app');

  // 👑 El dueño SIEMPRE cuenta como admin, no solo quien esté en la tabla de roles. Es la regla que
  // ya costó caro una vez: un panel que mira nada más la tabla deja al dueño afuera de su propia
  // app apenas cambia de email.
  const soyAdmin = MEITI.soyDuenoDeLaApp() || MEITI.miRolEnLaApp() === 'admin';

  const [pestana, setPestana] = React.useState('ayuda');
  const [filas, setFilas] = React.useState([]);
  const [cargando, setCargando] = React.useState(true);
  const [aviso, setAviso] = React.useState(null);

  // Un solo formulario para las dos pestañas: lo que cambia es la sección donde escribe.
  const VACIO = { titulo: '', cuerpo: '', tono: 'neutro' };
  const [editando, setEditando] = React.useState(null);
  const [forma, setForma] = React.useState(VACIO);
  const [abierto, setAbierto] = React.useState(false);

  const cargar = async () => {
    setCargando(true);
    const r = await MEITI.fetchDatos(base + '?ecosistema=' + eco);
    if (r.ok) setFilas(r.registros);
    setCargando(false);
  };

  React.useEffect(() => { cargar(); }, []);

  const cerrarFormulario = () => { setAbierto(false); setEditando(null); setForma(VACIO); };

  const guardar = async () => {
    if (!forma.titulo.trim()) { setAviso('Ponle un título antes de guardar.'); return; }
    const fila = editando || {};
    // 🩹 /api/boveda hace INSERT OR REPLACE por "id": si no se mandan TODAS las columnas, las que
    // falten quedan en NULL al reemplazar. Por eso el cuerpo va completo siempre, no solo lo tocado.
    const cuerpo = {
      id: fila.id || (pestana + '_' + Date.now()),
      seccion: pestana,
      titulo: forma.titulo.trim(),
      cuerpo: forma.cuerpo,
      tono: forma.tono || 'neutro',
      orden: fila.orden != null ? fila.orden : filas.filter(f => f.seccion === pestana).length,
      fecha: fila.fecha || new Date().toISOString()
    };
    const r = await MEITI.fetchMutante(base + '?ecosistema=' + eco + (editando ? '&id=' + fila.id : ''), {
      method: editando ? 'PUT' : 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify(cuerpo)
    });
    if (r && r.ok === false) { setAviso('No se pudo guardar. Vuelve a intentarlo.'); return; }
    setAviso(null);
    cerrarFormulario();
    cargar();
  };

  const borrar = async (fila) => {
    if (!await MEITI.confirmar('¿Borrar "' + (fila.titulo || 'este registro') + '"?', { titulo: MEITI.t('delete_action', null, 'Borrar'), confirmar: MEITI.t('delete_confirm', null, 'Sí, borrar'), tono: 'peligro' })) return;
    const r = await MEITI.fetchMutante(base + '?ecosistema=' + eco + '&id=' + fila.id, { method: 'DELETE' });
    if (r && r.ok === false) { setAviso('No se pudo borrar. Vuelve a intentarlo.'); return; }
    cargar();
  };

  const abrirEdicion = (fila) => {
    setEditando(fila);
    setForma({ titulo: fila.titulo || '', cuerpo: fila.cuerpo || '', tono: fila.tono || 'neutro' });
    setAbierto(true);
  };

  const deLaSeccion = filas.filter(f => (f.seccion || 'ayuda') === pestana);
  // La ayuda se lee en el orden en que el dueño la escribió; la bitácora, al revés: lo último
  // que pasó es lo primero que uno quiere ver.
  const visibles = pestana === 'ayuda'
    ? deLaSeccion.slice().sort((a, b) => (a.orden || 0) - (b.orden || 0))
    : deLaSeccion.slice().sort((a, b) => String(b.fecha || '').localeCompare(String(a.fecha || '')));

  const fechaLegible = (v) => {
    const m = /^(\d{4})-(\d{2})-(\d{2})/.exec(String(v || ''));
    if (!m) return '';
    const MESES = ['ene', 'feb', 'mar', 'abr', 'may', 'jun', 'jul', 'ago', 'sep', 'oct', 'nov', 'dic'];
    return Number(m[3]) + ' ' + MESES[Number(m[2]) - 1] + ' ' + m[1];
  };

  const TONOS = [
    { value: 'neutro', label: MEITI.t('note_input', null, 'Nota') },
    { value: 'exito', label: MEITI.t('update_input', null, 'Actualización') },
    { value: 'alerta', label: MEITI.t('notice_input', null, 'Aviso') },
    { value: 'peligro', label: MEITI.t('error_input', null, 'Error') }
  ];
  const nombreDelTono = (t) => (TONOS.find(x => x.value === (t || 'neutro')) || TONOS[0]).label;

  const filaAyuda = (f) => (
    <div key={f.id} style={{ border: '1px solid ' + tema.colorPrimario + '22', borderRadius: '0.75rem', padding: '1rem', marginBottom: '0.75rem' }}>
      <div style={{ display: 'flex', alignItems: 'flex-start', justifyContent: 'space-between', gap: '0.75rem' }}>
        <strong style={{ color: tema.texto }}>{f.titulo}</strong>
        {soyAdmin && (
          <div style={{ display: 'flex', gap: '0.25rem', flexShrink: 0 }}>
            <UI.Boton variante="fantasma" ariaLabel={MEITI.t('edit_action', null, "Editar")} onClick={() => abrirEdicion(f)}><i className="fa-solid fa-pen-to-square"></i></UI.Boton>
            <UI.Boton variante="fantasma-peligro" ariaLabel={MEITI.t('delete_action', null, "Borrar")} onClick={() => borrar(f)}><i className="fa-solid fa-trash-can"></i></UI.Boton>
          </div>
        )}
      </div>
      {f.cuerpo && <p style={{ color: tema.texto, opacity: 0.8, marginTop: '0.5rem', whiteSpace: 'pre-wrap' }}>{f.cuerpo}</p>}
    </div>
  );

  const filaBitacora = (f) => (
    <div key={f.id} style={{ display: 'flex', alignItems: 'flex-start', justifyContent: 'space-between', gap: '0.75rem', borderBottom: '1px solid ' + tema.colorPrimario + '18', padding: '0.6rem 0' }}>
      <div style={{ minWidth: 0 }}>
        <div style={{ display: 'flex', alignItems: 'center', gap: '0.5rem', flexWrap: 'wrap' }}>
          <UI.Chip tono={f.tono || 'neutro'}>{nombreDelTono(f.tono)}</UI.Chip>
          <strong style={{ color: tema.texto }}>{f.titulo}</strong>
        </div>
        {f.cuerpo && <p style={{ color: tema.texto, opacity: 0.75, marginTop: '0.35rem', whiteSpace: 'pre-wrap' }}>{f.cuerpo}</p>}
      </div>
      <div style={{ display: 'flex', alignItems: 'center', gap: '0.5rem', flexShrink: 0 }}>
        <span style={{ color: tema.texto, opacity: 0.5, fontSize: '0.75rem', whiteSpace: 'nowrap' }}>{fechaLegible(f.fecha)}</span>
        {soyAdmin && <UI.Boton variante="fantasma-peligro" ariaLabel={MEITI.t('delete_action', null, "Borrar")} onClick={() => borrar(f)}><i className="fa-solid fa-trash-can"></i></UI.Boton>}
      </div>
    </div>
  );

  return (
    <UI.Tarjeta>
      <h3 style={{ color: tema.texto, fontSize: '1.2rem', fontWeight: 'bold', marginBottom: '0.25rem' }}>{MEITI.t('configuration_title', null, "Configuración")}</h3>
      <p style={{ color: tema.texto, opacity: 0.6, fontSize: '0.75rem', marginBottom: '1rem' }}>{MEITI.t('app_guide_description', null, "Cómo se usa esta app, y qué le fue pasando.")}</p>

      {aviso && <UI.Aviso mensaje={aviso} tono="alerta" onCerrar={() => setAviso(null)} />}

      <UI.Pestanas
        pestanas={[{ id: 'ayuda', titulo: MEITI.t('help_title', null, 'Ayuda'), icono: 'fa-circle-question' }, { id: 'bitacora', titulo: MEITI.t('changelog_title', null, 'Bitácora'), icono: 'fa-clock-rotate-left' }]}
        activa={pestana}
        onCambio={(id) => { setPestana(id); cerrarFormulario(); }}
        className="mb-4"
      />

      {cargando ? (
        <p style={{ color: tema.texto, opacity: 0.6 }}>{MEITI.t('loading', null, "Cargando...")}</p>
      ) : visibles.length === 0 ? (
        <UI.EstadoVacio
          icono={pestana === 'ayuda' ? 'fa-book-open' : 'fa-clock-rotate-left'}
          mensaje={pestana === 'ayuda'
            ? (soyAdmin ? 'Todavía no hay guía de uso. Escribe la primera sección y quien entre después va a saber cómo usar la app.' : 'Todavía no hay una guía para esta app.')
            : 'Todavía no hay nada anotado. Acá van a aparecer las actualizaciones, los avisos y los errores de esta app.'}
        />
      ) : pestana === 'ayuda' ? (
        <div>{visibles.map(filaAyuda)}</div>
      ) : (
        <UI.ListaScrollable alto="26rem">{visibles.map(filaBitacora)}</UI.ListaScrollable>
      )}

      {soyAdmin && (
        <div style={{ marginTop: '1.25rem', paddingTop: '1rem', borderTop: '1px solid ' + tema.colorPrimario + '22' }}>
          {!abierto ? (
            <UI.Boton variante="secundario" onClick={() => setAbierto(true)}>
              <i className="fa-solid fa-plus"></i> {pestana === 'ayuda' ? 'Agregar una sección a la guía' : 'Anotar en la bitácora'}
            </UI.Boton>
          ) : (
            <div>
              <UI.Campo
                etiqueta={pestana === 'ayuda' ? 'Título de la sección' : 'Qué pasó'}
                valor={forma.titulo}
                onChange={(e) => setForma({ ...forma, titulo: e.target.value })}
                placeholder={pestana === 'ayuda' ? 'Cómo dar de alta un cliente' : 'Se actualizó el catálogo de precios'}
              />
              <div style={{ height: '0.75rem' }} />
              <UI.Campo
                etiqueta={pestana === 'ayuda' ? 'Explicación' : 'Detalle (opcional)'}
                tipo="textarea"
                filas={4}
                valor={forma.cuerpo}
                onChange={(e) => setForma({ ...forma, cuerpo: e.target.value })}
                placeholder={pestana === 'ayuda' ? 'Explícalo como se lo explicarías a alguien que abre la app por primera vez' : 'Qué se cambió y por qué'}
              />
              {pestana === 'bitacora' && (
                <div style={{ marginTop: '0.75rem' }}>
                  <UI.Campo etiqueta={MEITI.t('type_input', null, "Tipo")} tipo="select" valor={forma.tono} onChange={(e) => setForma({ ...forma, tono: e.target.value })} opciones={TONOS} />
                </div>
              )}
              <div style={{ height: '0.75rem' }} />
              <div style={{ display: 'flex', gap: '0.5rem' }}>
                <UI.Boton onClick={guardar}>{editando ? 'Guardar cambios' : 'Guardar'}</UI.Boton>
                <UI.Boton variante="secundario" onClick={cerrarFormulario}>{MEITI.t('cancel_button', null, "Cancelar")}</UI.Boton>
              </div>
            </div>
          )}
        </div>
      )}
    </UI.Tarjeta>
  );
}
